fn rule_0(m: &mut Matcher<'_>, root: ExprId) -> Option<ExprId> {
    let Expr::Binary(Binary::Add, e0, e1) = m.expr(root)? else {
        return None;
    };
    let v0 = e0;
    let w_w = m.width(v0)?;
    if !claimed(w_w, &[8, 16, 32, 64]) {
        return None;
    }
    if m.width(e1)? != w_w {
        return None;
    }
    if !m.literal(e1, w_w, 0i64) {
        return None;
    }
    let r0 = v0;
    Some(r0)
}
